// Bundles the compiled classifier, its feature code and the trained model into
// one plain script for the content script, so the web extension and the VS
// Code extension share the same rules and model. Run with: npm run build:web
//
// With --check it writes nothing and exits non-zero when the committed bundle
// is stale, so a core change that forgets to rebuild fails in the test run.
import { readFileSync, writeFileSync, existsSync } from "node:fs";

const out = (p) => new URL(`../out/src/core/${p}`, import.meta.url);
const strip = (src) => src.replace(/^\/\/# sourceMappingURL=.*$/m, "").trim();
const model = readFileSync(new URL("../resources/classifier-model.json", import.meta.url), "utf8");

// Dependency order: each module may only require ones defined before it, because
// `define` runs its body immediately.
const BUNDLED = ["types", "budget", "features", "signals", "classifier"];
const sources = Object.fromEntries(BUNDLED.map((name) => [name, strip(readFileSync(out(`${name}.js`), "utf8"))]));

BUNDLED.forEach((name, i) => {
  const available = new Set(BUNDLED.slice(0, i));
  for (const m of sources[name].matchAll(/require\("([^"]+)"\)/g)) {
    const dep = m[1].replace(/^\.\//, "");
    if (!available.has(dep)) {
      throw new Error(`${name}.js requires ${m[1]}, which is not bundled before it; update BUNDLED in web/build.mjs`);
    }
  }
});

const bundle = `// GENERATED by web/build.mjs from src/core/{${BUNDLED.join(",")}}.ts and resources/classifier-model.json. Do not edit; run "npm run build:web".
(() => {
const modules = {};
const define = (name, fn) => { const exports = {}; fn(exports); modules[name] = exports; };
const require = (name) => modules[name.replace(/^\\.\\//, "")];
${BUNDLED.map((name) => `define("${name}", (exports) => {\n${sources[name]}\n});`).join("\n")}
const model = ${model};
globalThis.claudeRouterClassify = (input) => modules.classifier.classify(input, model);
globalThis.claudeRouterTierToFamily = modules.types.TIER_TO_FAMILY;
})();
`;

const target = new URL("./classifier.js", import.meta.url);

if (process.argv.includes("--check")) {
  const current = existsSync(target) ? readFileSync(target, "utf8") : "";
  if (current !== bundle) {
    console.error("web/classifier.js is stale. Run: npm run build:web");
    process.exit(1);
  }
  console.log("web/classifier.js is up to date");
} else {
  writeFileSync(target, bundle);
  console.log("Wrote web/classifier.js");
}
